"use client";

/** Host adapter for the Apache-2.0 scan UI by Gustavo Fior (@gustavo-fior), Abdul Haidar, and Foglamp Labs. */
import { createContext, useContext, type ReactNode } from "react";
import { faviconUrl } from "../../lib/scan/favicon";

const FaviconContext = createContext(faviconUrl);

/** Supply your image endpoint or asset resolver without changing map markup. */
export function ScanFaviconProvider({ resolve, children }: {
  resolve: (domain: string) => string;
  children: ReactNode;
}) {
  return <FaviconContext.Provider value={resolve}>{children}</FaviconContext.Provider>;
}

export function useScanFavicon() {
  return useContext(FaviconContext);
}

/* Derived for the Foglamp Design System portal by the project contributors.
 * It adapts Foglamp concepts and assets; this new integration code is not represented as upstream-authored.
 * Original project: Gustavo Fior (@gustavo-fior), Abdul Haidar, Foglamp Labs; Apache-2.0 source project.
 */
export function faviconUrl(domain: string): string {
	return `/api/favicon?domain=${encodeURIComponent(domain)}`;
}

/**
 * Product-accurate icon domains for models: agents often emit the provider's
 * corporate domain (google.com → the "G"), but the model deserves its product
 * mark (Gemini's spark). Keyed by label match, applied only to model items.
 */
const MODEL_DOMAIN_FIXES: [RegExp, string][] = [
	[/gemini/i, "gemini.google.com"],
	[/claude/i, "claude.ai"],
	[/gpt|^o[0-9]/i, "openai.com"],
];

export function modelDomain(
	label: string,
	domain?: string,
): string | undefined {
	for (const [re, fixed] of MODEL_DOMAIN_FIXES) {
		if (re.test(label)) return fixed;
	}
	return domain;
}
